cd /workspace/dataset
probe(){ printf '%-20q -> ' "$1"; ./test20_executable "$1" | sed -n '1p' | od -c | head -3; }
for w in 'gold fish' 'a fish' 'fish ' ' fish' 'fish!' 'fish.' 'gold-fish' 'fish-gold' 'Fish fish' 'fish_x' 'x_fish' 'the police' 'police officer'; do probe "$w"; done

cd /workspace/dataset
perl -e '
use strict; use warnings;
srand(7);
my %UNC = map {$_=>1} qw(equipment information rice money species series fish sheep jeans police);
my @alpha = map { chr($_) } grep { $_ != 10 } (1..255);
my @words;
for (1..800) { my $L=1+int(rand(12)); push @words, join("", map { $alpha[int(rand(@alpha))] } 1..$L); }
my @asc = split //, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 -_.\x27";
for (1..600) { my $L=1+int(rand(10)); push @words, join("", map { $asc[int(rand(@asc))] } 1..$L); }
for my $u (keys %UNC) { push @words, $u, uc($u), ucfirst($u), $u.$u, substr($u,0,-1), $u."s", " $u", "$u "; }
push @words, "a" x 100000;
push @words, "fish" x 25000;
my ($n,$f)=(0,0);
for my $w (@words) {
  next if $w eq "";
  $n++;
  open(my $ph, "-|", "./test20_executable", $w) or die;
  local $/; my $out = <$ph>; close $ph;
  my ($line1) = split(/\n/, $out, 2);
  $line1 = "" unless defined $line1;
  my $exp = $UNC{$w} ? $w : $w."s";
  if ($line1 ne $exp) { $f++; if ($f<=25) { printf("MISMATCH w=%s got=%s exp=%s\n", unpack("H*",substr($w,0,40)), unpack("H*",substr($line1,0,40)), unpack("H*",substr($exp,0,40))); } }
}
print "probes=$n fails=$f\n";
'

apis.rust_sketch:
const UNCOUNTABLE: [&str; 10] = [
    "equipment", "information", "rice", "money", "species",
    "series", "fish", "sheep", "jeans", "police",
];

/// Byte-exact reimplementation of line 1 of test20_executable.
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    // Whole-string, case-sensitive, byte-for-byte comparison.
    for u in UNCOUNTABLE.iter() {
        if word == u.as_bytes() {
            return word.to_vec();
        }
    }
    let mut out = Vec::with_capacity(word.len() + 1);
    out.extend_from_slice(word);
    out.push(b's');
    out
}

// String convenience wrapper (input may be non-UTF8 in general; prefer &[u8]).
pub fn pluralize_str(word: &str) -> String {
    if UNCOUNTABLE.contains(&word) {
        word.to_string()
    } else {
        let mut s = String::with_capacity(word.len() + 1);
        s.push_str(word);
        s.push('s');
        s
    }
}
